fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Use zip to pair elements, then map to compare, and collect into Vec<bool>
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x >= y)
        .collect()
}